function validate([target, startFuel, stations]) {
  if (!Number.isInteger(target) || target < 1 || target > 1e9) return 'target is an integer from 1 to 10^9.';
  if (!Number.isInteger(startFuel) || startFuel < 1 || startFuel > 1e9) return 'startFuel is an integer from 1 to 10^9.';
  if (!Array.isArray(stations) || stations.length > 500) return 'There are at most 500 stations.';
  let previous = 0;
  for (const station of stations) {
    if (!Array.isArray(station) || station.length !== 2) return 'Each station is a [position, fuel] pair.';
    const [position, fuel] = station;
    if (!Number.isInteger(position) || position <= previous) return 'Station positions are at least 1 and strictly increasing.';
    if (position >= target) return 'Every station lies before target.';
    if (!Number.isInteger(fuel) || fuel < 1 || fuel >= 1e9) return 'Each station has 1 to 10^9 - 1 liters.';
    previous = position;
  }
  return null;
}

