function minRefuelStops(target, startFuel, stations) {
  // farthest[k] = farthest distance reachable using exactly k of the stations seen so far.
  const farthest = [startFuel];
  for (const [position, fuel] of stations) {
    farthest.push(-1);
    for (let k = farthest.length - 2; k >= 0; k--) {
      if (farthest[k] >= position) farthest[k + 1] = Math.max(farthest[k + 1], farthest[k] + fuel);
    }
  }
  for (let k = 0; k < farthest.length; k++) if (farthest[k] >= target) return k;
  return -1;
}

