function generate(rand, size) {
  const large = size === 'large';
  const target = large ? 1000000000 - Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 60);
  const room = target - 1;
  const n = Math.min(room, large ? 500 : Math.floor(rand() * 8));
  const chosen = new Set();
  while (chosen.size < n) chosen.add(1 + Math.floor(rand() * room));
  const positions = [...chosen].sort((a, b) => a - b);
  const gap = Math.max(1, Math.floor(target / (n + 1)));
  const spread = large ? 2.5 + rand() * 2 : 3;
  const stations = positions.map(position => [position, Math.min(999999999, 1 + Math.floor(rand() * spread * gap))]);
  let startFuel = 1 + Math.floor(rand() * (large ? 2 : 3) * gap);
  if (large && rand() < 0.85) {
    // Most large cases are made reachable by topping up the fuel just before each shortfall.
    let total = startFuel;
    for (let i = 0; i <= n; i++) {
      const position = i < n ? stations[i][0] : target;
      if (position > total) {
        const extra = position - total + Math.floor(rand() * gap);
        if (i === 0) startFuel += extra; else stations[i - 1][1] += extra;
        total += extra;
      }
      if (i < n) total += stations[i][1];
    }
  }
  return [target, Math.min(1000000000, startFuel), stations];
}
